```ts
#!/usr/bin/env bun
/**
 * dispatch_rejected.ts — return a pull request that was closed WITHOUT merging to
 * the agent that opened it, as a rejection.
 * ...
 */

import { dispatchRejectedPrAgent } from "../../adapters/actions/dispatch-targets.ts";
import { ORIGIN_AGENT_TAG } from "../../adapters/github/tags.ts";
import { readTargetState } from "../../adapters/github/target-state.ts";
import { decideRejectionHandoff } from "../../domain/work/handoff.ts";
import { defineScript } from "./lib/script-ref.ts";

export const ref = defineScript(import.meta.url);

function main(): void {
  const body = process.env.PR_BODY ?? "";
  const prNumber = (process.env.PR_NUMBER ?? "").trim();
  const issueRaw = (process.env.ISSUE_NUMBER ?? "").trim();
  const repo = `${process.env.OWNER ?? ""}/${process.env.REPO ?? ""}`;

  const say = (message: string): void => console.error(message);

  // From `parse`, not from the body: parse already read the tag for the merge-side
  // jobs, and a second reader of the same tag is the shape this repository removes.
  const issueNumber = issueRaw === "" ? undefined : Number(issueRaw);
  // Read, not assumed (same as dispatch_post_merge.ts): an unread state is treated
  // as NOT closed, so the judgement is preferred over a silent stand-down.
  const state = issueNumber === undefined ? undefined : readTargetState(issueNumber, repo);
  const issueAlreadyClosed = state?.known === true && state.state !== "open";
  const originAgent = ORIGIN_AGENT_TAG.read(body);

  const handoff = decideRejectionHandoff({ parentIssue: issueNumber, parentAlreadyClosed: issueAlreadyClosed, originAgent });

  switch (handoff.kind) {
    case "nothing":
      say(`PR #${prNumber} was closed without merging; nothing re-invoked (${handoff.why}).`);
      return;
    case "reinvoke-origin-agent": {
      const dispatched = dispatchRejectedPrAgent(repo, handoff.parentIssue, handoff.agent, Number(prNumber));
      if (dispatched) {
        say(`Re-invoked ${handoff.agent} on #${handoff.parentIssue} to judge the rejection.`);
        return;
      }
      // No fallback exists on this side. The merge route stands the aggregate job up
      // when its dispatch fails; the rejection route has nothing to fall back to --
      // silence here is the exact defect #267 exists to remove ("a person closed the
      // pull request and nobody said anything"), so the job goes red instead.
      say(`Could not re-invoke ${handoff.agent} on #${handoff.parentIssue}; failing the job rather than ending silently.`);
      process.exit(1);
    }
  }
}

if (import.meta.main) main();
```

